(function(){'use strict';let connection;
function db(){if(!connection)connection=new Promise((resolve,reject)=>{let r=indexedDB.open('engefex-gerenciamento-files-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>{connection=null;reject(Error('Não foi possível abrir os anexos locais.'))}});return connection;}
async function transaction(mode,fn){let database=await db();return new Promise((resolve,reject)=>{let tx=database.transaction('files',mode),store=tx.objectStore('files'),result;fn(store,v=>result=v);tx.oncomplete=()=>resolve(result);tx.onerror=tx.onabort=()=>reject(Error('Não foi possível ler ou salvar anexos. Confira o espaço do aparelho.'))})}
async function load(ids){if(!ids.length)return [];return transaction('readonly',(s,set)=>{let values=new Array(ids.length);ids.forEach((id,i)=>{let r=s.get(id);r.onsuccess=()=>{values[i]=r.result;set(values)}})}).then(files=>{if(files.some(x=>!x))throw Error('Anexo ausente. Importe um backup que contenha os arquivos.');return files})}
const put=files=>files.length?transaction('readwrite',s=>{for(let f of files)s.put(f)}):Promise.resolve();
async function prepare(file){if(file.size>20000000)throw Error('Limite por arquivo: 20 MB.');let dataURL,width,height;if(file.type.startsWith('image/')){let url=URL.createObjectURL(file),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Imagem incompatível. Use JPEG ou PNG.'));image.src=url});let scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight));width=Math.round(image.naturalWidth*scale);height=Math.round(image.naturalHeight*scale);let c=document.createElement('canvas');c.width=width;c.height=height;let ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,width,height);ctx.drawImage(image,0,0,width,height);dataURL=c.toDataURL('image/jpeg',.86)}finally{URL.revokeObjectURL(url)}}else dataURL=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Falha ao ler anexo.'));r.readAsDataURL(file)});return {id:AppModel.id(),name:file.name,type:width?'image/jpeg':file.type||'application/octet-stream',dataURL,width,height}}
function refs(state){return [...new Set(Object.values(state).filter(Array.isArray).flatMap(rows=>rows.flatMap(r=>(r.attachments||[]).map(f=>f.id))))]}
window.LocalFiles={load,put,prepare,refs};})();
